components.css:
.ds-nav { min-height: 72px; display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.55rem 1rem 0.55rem 1.15rem; border: 1px solid rgba(255,255,255,0.78); border-radius: 999px; background: rgba(255,255,255,0.78); box-shadow: 0 12px 30px rgba(60,33,65,0.1); backdrop-filter: blur(24px) saturate(165%); color: var(--ink); font: 800 0.75rem/1.2 var(--font-ui); }
.ds-nav__mark, .ds-nav__links a { color: inherit; text-decoration: none; }
.ds-nav__links { display: flex; align-items: center; gap: 0.28rem; }
.ds-nav__links a { min-height: 42px; display: inline-flex; align-items: center; padding: 0.5rem 0.82rem; border-radius: 999px; }
.ds-nav__links a:hover, .ds-nav__links a[aria-current="page"] { background: #f4e7f1; color: #78284f; }
.ds-nav__admin { background: #2e1c34; color: #fff !important; }
.ds-nav a:focus-visible { outline: 3px solid var(--brass); outline-offset: 3px; }
@media (max-width: 680px) { .ds-nav { flex-wrap: wrap; border-radius: 25px; } .ds-nav__links { width: 100%; overflow-x: auto; } }

.ds-button { min-height: 48px; display: inline-flex; align-items: center; justify-content: center; gap: 0.55rem; padding: 0.74rem 1.15rem; border: 1px solid rgba(41,23,47,0.12); border-radius: 999px; font: 800 0.75rem/1.2 var(--font-ui); text-decoration: none; transition: background 180ms ease, color 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease; }
.ds-button svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.ds-button--primary { border-color: #fff; background: #fff; color: #552345; box-shadow: 0 8px 20px rgba(24,7,29,0.16); }
.ds-button--primary:hover { transform: translateY(-2px); border-color: #ffd2e2; background: #ffd2e2; color: #401a38; }
.ds-button:focus-visible { outline: 3px solid var(--brass); outline-offset: 3px; }
.ds-button:active { transform: translateY(0); }
@media (prefers-reduced-motion: reduce) { .ds-button { transition: none; } }

.ds-button-glass { min-height: 48px; display: inline-flex; align-items: center; justify-content: center; gap: 0.55rem; padding: 0.74rem 1.15rem; border: 1px solid rgba(255,255,255,0.54); border-radius: 999px; background: rgba(255,255,255,0.13); color: #fff; backdrop-filter: blur(18px); font: 800 0.75rem/1.2 var(--font-ui); text-decoration: none; transition: background 180ms ease, border-color 180ms ease, transform 180ms ease; }
.ds-button-glass svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.ds-button-glass:hover { transform: translateY(-2px); border-color: rgba(255,255,255,0.85); background: rgba(255,255,255,0.24); }
.ds-button-glass:focus-visible { outline: 3px solid var(--brass); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-button-glass { transition: none; } }

.ds-chip { min-height: 47px; display: inline-flex; align-items: center; gap: 0.55rem; padding: 0.58rem 0.88rem 0.58rem 0.55rem; border: 1px solid rgba(66,43,73,0.12); border-radius: 999px; background: rgba(255,255,255,0.68); box-shadow: 0 5px 14px rgba(60,38,69,0.045); color: #3e2b45; font: 750 0.72rem/1.2 var(--font-ui); text-decoration: none; transition: transform 170ms ease, background 170ms ease, border-color 170ms ease, box-shadow 170ms ease; }
.ds-chip__brand { padding: 0.2rem 0.46rem; border-radius: 999px; background: #f4e8f5; color: #693a78; font-size: 0.6rem; font-weight: 850; white-space: nowrap; }
.ds-chip:hover, .ds-chip[aria-current="page"] { transform: translateY(-2px); border-color: rgba(156,54,108,0.42); background: #642653; color: #fff; }
.ds-chip:focus-visible { outline: 3px solid var(--brass); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-chip { transition: none; } }

.ds-brand-launcher { min-height: 86px; display: flex; align-items: center; gap: 0.8rem; padding: 0.75rem 1rem 0.75rem 0.78rem; border: 1px solid rgba(255,255,255,0.62); border-radius: 999px; background: rgba(255,249,255,0.2); box-shadow: 0 16px 32px rgba(32,9,38,0.19); color: #fff; backdrop-filter: blur(22px) saturate(150%); text-decoration: none; transition: transform 180ms ease, background 180ms ease, box-shadow 180ms ease; }
.ds-brand-launcher__mark { width: 55px; height: 55px; display: grid; place-items: center; flex: 0 0 auto; border: 1px solid rgba(255,255,255,0.76); border-radius: 50%; background: rgba(255,255,255,0.2); font: 850 0.86rem/1 var(--font-ui); }
.ds-brand-launcher__copy { display: grid; gap: 0.08rem; flex: 1; }
.ds-brand-launcher__copy small { color: #f7d9e9; font: 650 0.61rem/1.2 var(--font-ui); }
.ds-brand-launcher__copy strong { font: 560 1.27rem/1.1 var(--font-display); letter-spacing: -0.02em; }
.ds-brand-launcher svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.ds-brand-launcher:hover { transform: translateY(-4px) scale(1.015); background: rgba(255,250,255,0.3); box-shadow: 0 22px 40px rgba(32,9,38,0.24); }
.ds-brand-launcher:focus-visible { outline: 3px solid var(--brass); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-brand-launcher { transition: none; } }

.ds-field { display: grid; gap: 0.38rem; color: var(--ink); font: 700 0.75rem/1.4 var(--font-ui); }
.ds-field input { width: 100%; min-height: 46px; padding: 0.65rem 0.72rem; border: 1px solid rgba(67,43,73,0.22); border-radius: 14px; background: #fff; color: var(--ink); font: 400 15px/1.6 var(--font-ui); }
.ds-field input:focus-visible { outline: 3px solid rgba(203,93,148,0.32); border-color: #a1396b; }

.ds-hero { min-height: 510px; padding: clamp(2rem,6.5vw,5.4rem); border: 1px solid rgba(255,255,255,0.46); border-radius: 42px; background: radial-gradient(ellipse at 79% 13%,rgba(255,190,220,0.36),transparent 23rem), radial-gradient(ellipse at 19% 102%,rgba(128,72,154,0.56),transparent 31rem), linear-gradient(126deg,#32173d 4%,#642653 56%,#8c3a70 100%); box-shadow: 0 24px 54px rgba(62,25,68,0.2); color: #fff9fc; }
.ds-hero h1 { max-width: 10ch; margin: 0; font: 520 clamp(3.2rem,6vw,5.7rem)/0.94 var(--font-display); letter-spacing: -0.052em; }
.ds-hero h1 span { color: #ffc4d8; }
.ds-hero p { max-width: 48ch; color: #f4e8f2; font: 400 clamp(0.9rem,1.2vw,1.05rem)/1.7 var(--font-ui); }
@media (max-width: 680px) { .ds-hero { min-height: 0; border-radius: 32px; } .ds-hero h1 { font-size: clamp(3.15rem,13.8vw,4.6rem); } }
